mapper.update:
update red_packet
set status = #{status}
where packet_no = #{packetNo}

update red_packet
set remain_amount = remain_amount - #{amount},
    remain_count  = remain_count - #{count}
where packet_no = #{packetNo}

mapper.select:
select count(1)
from red_packet_record
where packet_no = #{packetNo}
  and user_id = #{userId}
